widget.solution:
def bond_price(y, coupon, years, face):
    pv = sum(coupon / (1 + y) ** t for t in range(1, years + 1))
    return pv + face / (1 + y) ** years


def yield_for_price(price, coupon, years, face):
    lo, hi = 0.0, 1.0
    if price > bond_price(lo, coupon, years, face):
        return None
    if price < bond_price(hi, coupon, years, face):
        return None
    while True:
        mid = (lo + hi) / 2
        p = bond_price(mid, coupon, years, face)
        if abs(p - price) <= 0.01:
            return mid
        if p > price:
            lo = mid
        else:
            hi = mid
